def f(x):
    return x**3 + 4*x**2 - 3*x + 8

def f_prime(x):
    return 3*x**2 + 8*x - 3

def newtons_method(x0, max_iter=100):
    x = x0
    iterations = []

    for i in range(max_iter):
        fx = f(x)
        fpx = f_prime(x)

        if fpx == 0:
            break

        x_next = x - fx/fpx

        iterations.append({
            'n': i,
            'x_n': x,
            'x_n_rounded': round(x, 4),
            'x_next': x_next,
            'x_next_rounded': round(x_next, 4)
        })

        x = x_next

    return iterations

# Run Newton's method starting from x_0 = -5
iterations = newtons_method(-5)

# Check when rounded values become equal
for i, iter_data in enumerate(iterations):
    if iter_data['x_n_rounded'] == iter_data['x_next_rounded']:
        print(f"Found convergence at n={i}: x_n_rounded={iter_data['x_n_rounded']}, x_next_rounded={iter_data['x_next_rounded']}")
        break
else:
    print("No convergence found")
